INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21501, 'Micah 3:8', 'Micah', 3, 8, '&nbsp;خو زۀ په خپله د قدرت نه، د مالِک خُدائ د روح نه، او د اِنصاف او د قوت نه معمور يم، چې يعقوب ته خپل جرمونه، او بنى اِسرائيلو ته خپله ګناه وښايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21502, 'Micah 3:9', 'Micah', 3, 9, '&nbsp;دې ته غوږ شئ، اے د يعقوب د قوم مشرانو، او د اِسرائيل د قوم حکمرانانو، څوک چې اِنصاف نه نفرت کوئ او هغه هر څۀ غلطوئ چې صحيح وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21503, 'Micah 3:10', 'Micah', 3, 10, '&nbsp;څوک چې صيون په قتل عام جوړَوئ، او يروشلم په بدعملۍ جوړَوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21504, 'Micah 3:11', 'Micah', 3, 11, '&nbsp;د دې حکمرانان په رشوت اخستو عدالت کوى، د دې اِمامان په پېسو تعليم ورکوى، او د دې پېغمبران په پېسو پېشګوئې کوى، او په مالِک خُدائ د باور کولو دعوىٰ کوى خو په حقيقت کښې په هغۀ باور نۀ کوى، او داسې وائى چې، ”آيا مالِک خُدائ زمونږ په مينځ کښې نۀ دے؟ په مونږ به هيڅ افت رانۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21505, 'Micah 3:12', 'Micah', 3, 12, '&nbsp;نو ځکه ستاسو په وجه، صيون به لکه د پټى غوندې يوه کړے شى، يروشلم نه به د کنډر يو ډېرے جوړ شى، او د خُدائ پاک د کور په غر به ګڼ ځنګل وشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21506, 'Micah 4:1', 'Micah', 4, 1, '&nbsp;په آخرى ورځو کښې به د مالِک خُدائ د کور غر آباد شى او دا به په ټولو غرونو کښې مشر وى، دا به د غرونو دپاسه اوچت شى، او د ډېرو قومونو خلق به ورته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21507, 'Micah 4:2', 'Micah', 4, 2, '&nbsp;ډېر قومونه به راشى او وائى به، ”راځئ چې بره د مالِک خُدائ غر ته لاړ شُو، د يعقوب د خُدائ پاک کور ته. هغه به مونږ ته خپلې طريقې وښائى، نو چې مونږ د هغۀ په لار روان شُو.“ شريعت به صيون نه راوځى، او د خُدائ پاک کلام به د يروشلم نه راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21508, 'Micah 4:3', 'Micah', 4, 3, '&nbsp;هغه به د ډېرو قومونو په مينځ کښې عدالت وکړى، او د لرې او نزدې مضبوطو حکومتونو لانجې به فېصله کړى. هغوئ به خپلې تُورې وټکوى او يوې به ورنه جوړې کړى او د خپلو نېزو نه به د بوټو قينچيانې جوړې کړى. قوم به د قوم خلاف تُوره نۀ اوچتوى، او نۀ به هغوئ د جنګ کولو تربيت حاصلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21509, 'Micah 4:4', 'Micah', 4, 4, '&nbsp;هر يو کس به د خپل انګور د بوټى لاندې او د خپلو اينځرو د ونو لاندې کښېنى، او څوک به هم هغوئ ونۀ ويروى. ځکه چې دا مالِک خُدائ ربُ الافواج فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21510, 'Micah 4:5', 'Micah', 4, 5, '&nbsp;هر يو قوم به د خپلو معبودانو په نوم روان وى، خو مونږ به د مالِک خُدائ د خپل خُدائ پاک په نوم د تل دپاره روان يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21511, 'Micah 4:6', 'Micah', 4, 6, '&nbsp;”په هغه ورځ،“ مالِک خُدائ فرمائى چې، ”زۀ به ګوډيان راغونډ کړم، زۀ به جلاوطن شوى راجمع کړم او هغوئ چې ما ورته غم و درد رسولے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21512, 'Micah 4:7', 'Micah', 4, 7, '&nbsp;زۀ به د ماتو ګوډو او د هغوئ نه څوک چې جلاوطن کړے شوى دى يوه ډله بچ کړم چې يو مضبوط قوم ترې جوړ کړم. زۀ مالِک خُدائ به په هغوئ د هغې ورځ نه واخله د تل دپاره د يروشلم نه حکومت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21513, 'Micah 4:8', 'Micah', 4, 8, '&nbsp;او ترڅو چې تۀ يې، اے د رمې حفاظت کوونکيه، اے د صيون لور مضبوطې قلعې، پخوانے حکومت به تا ته بيا مِلاو شى، او بادشاهت به بيا يروشلم لور ته مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21514, 'Micah 4:9', 'Micah', 4, 9, '&nbsp;تۀ اوس دومره په چغو ولې ژاړې، آيا ستا بادشاه نشته؟ آيا ستا مشيران مړۀ شوى دى، درد تۀ داسې ګېر کړے يې لکه چې ښځه د ماشوم د پېدا کېدو په درد کښې وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21515, 'Micah 4:10', 'Micah', 4, 10, '&nbsp;اے د صيون لورې، داسې د درد نه چغې او ټوپونه ووهه، لکه چې ښځه د ماشوم پېدا کېدو په وخت وهى، ځکه چې اوس به تاسو خامخا ښار پرېږدئ او په کولاو مېدان کښې به اوسېږئ. تۀ به بابل ته لاړه شې، خو تۀ به هلته بچ کړے شې. هلته به مالِک خُدائ تا د خپلو دشمنانو د لاسونو نه د تاوان په بدله را آزاده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21516, 'Micah 4:11', 'Micah', 4, 11, '&nbsp;نو اوس ډېر قومونه ستا خِلاف راغونډ شوى دى. هغوئ وائى، ”پرېږدئ چې هغه بې‌عزته شى، او پرېږده چې زمونږ سترګې په شوق سره صيون ته وګورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21517, 'Micah 4:12', 'Micah', 4, 12, '&nbsp;خو دوئ ته د مالِک خُدائ د سوچونو پته نشته، هغوئ ته د هغۀ د منصوبې پته نشته، هغه هغوئ درمند ته لکه د ګېډو په شان راغونډوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21518, 'Micah 4:13', 'Micah', 4, 13, '&nbsp;پاڅه او مُلکونه غوبل کړه، اے صيون لورې، ځکه چې زۀ به تا له د اوسپنې ښکر درکړم، زۀ به تا ته د پيتلو نوکونه درکړم او تۀ به ډېر قومونه ټوټه ټوټه کړې. تۀ به د هغوئ هغه مال چې په ظلم زياتى يې حاصل کړے دے مالِک خُدائ ته وقف کړې او د هغوئ دولت به د ټولې دُنيا مالِک ته پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21519, 'Micah 5:1', 'Micah', 5, 1, '&nbsp;خپل فوج راغونډ کړه، اے د فوجيانو ښاريې، ځکه چې زمونږ خلاف محاصره شوې ده. هغوئ به د اِسرائيل مشر په چوکې سره په مخ ووهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21520, 'Micah 5:2', 'Micah', 5, 2, '&nbsp;خو تۀ، اے د بيت‌لحم اِفراته، اګر کۀ تۀ د يهوداه په قبيلو کښې وړه يې، خو تا نه به ما دپاره هغه راشى څوک چې به د اِسرائيل سردار وى، د هغۀ نسب زوړ دے، او د پخوانۍ زمانې نه راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21521, 'Micah 5:3', 'Micah', 5, 3, '&nbsp;نو بنى اِسرائيل به تر هغه وخته پورې خپلو دشمنانو ته پرېښودلے شى ترڅو چې د يوې اُميدوارې ښځې د ماشوم د پېدا کېدو وخت پوره شى. او چې د هغۀ نور وروڼه د بنى اِسرائيلو سره د اِتحاد کولو دپاره راواپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21522, 'Micah 5:4', 'Micah', 5, 4, '&nbsp;هغه به د خپلو رمو د شپونتوب دپاره ودريږى د مالِک خُدائ په طاقت سره، د مالِک خپل خُدائ پاک د نوم په رُعب سره. او هغوئ به په امن سره اوسيږى، نو بيا به د هغۀ عظمت د دُنيا آخرى حدونو ته ورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21523, 'Micah 5:5', 'Micah', 5, 5, '&nbsp;او هغه به د هغوئ سلامتيا سرچينه وى. خلاصون او سزا کله چې اسوريان زمونږ په مُلک حمله وکړى او زمونږ په پَخو دېوالونو راواوړى، مونږ به د هغوئ خلاف د قوم اووۀ مشران، او ورسره اتۀ حکمرانان هم راوچت کړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21524, 'Micah 5:6', 'Micah', 5, 6, '&nbsp;هغوئ به د تُورې په زور د اسوريى په مُلک، او د نمرود په مُلک به د تُورې په زور حکومت کوى. هغه به مونږ د اسوريانو نه خلاص کړى کله چې هغوئ زمونږ په مُلک باندې حمله وکړى او زمونږ سرحدونو ته راننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21525, 'Micah 5:7', 'Micah', 5, 7, '&nbsp;د يعقوب پاتې شوى خلق به د ډېرو قومونو په مينځ کښې لکه د مالِک خُدائ د رالېږلے شوې پرخې يا په واښو د باران په شان وى، کوم چې د انسان انتظار نۀ کوى او نۀ د انسان دپاره ايساريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21526, 'Micah 5:8', 'Micah', 5, 8, '&nbsp;د يعقوب پاتې شوى به د قومونو په مينځ کښې وى، د ډېرو قومونو په مينځ کښې، لکه چې شير د ځنګلى ځناورو په مينځ کښې وى، يا لکه چې ځوان شير د ګډو د رمو په مينځ کښې وى، چې دے روان وى نو په پنجه وهل کوى او ماتول کوى، او هيڅ څوک ترې نه ځان نۀ شى بچ کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21527, 'Micah 5:9', 'Micah', 5, 9, '&nbsp;تاسو به په کاميابۍ سره په خپلو دشمنانو بريالى شئ، او ټول دشمنان به مو تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21528, 'Micah 5:10', 'Micah', 5, 10, '&nbsp;”په هغه ورځ،“ مالِک خُدائ فرمائى، ”زۀ به ستاسو آسونه تباه کړم ستاسو په مينځ کښې او ستاسو جنګى ګاډۍ به ختمې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21529, 'Micah 5:11', 'Micah', 5, 11, '&nbsp;زۀ به ستاسو د مُلک ښارونه تباه کړم او ستاسو ټولې مضبوطې قلعه ګانې به راوغورزوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21530, 'Micah 5:12', 'Micah', 5, 12, '&nbsp;زۀ به ستا جادوګر تباه کړم او ستاسو په مينځ کښې به فالګر نور نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21531, 'Micah 5:13', 'Micah', 5, 13, '&nbsp;زۀ به ستاسو تراشلے شوى بُتان او مقدس کاڼى ستاسو مينځ نه تباه کړم، تاسو به نور د خپل لاس جوړ شوى څيزونو ته سجده نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21532, 'Micah 5:14', 'Micah', 5, 14, '&nbsp;زۀ به ستاسو د مينځ نه د اشيرې بُت ستنې راوکاږم او ستاسو ښارونه به تباه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21533, 'Micah 5:15', 'Micah', 5, 15, '&nbsp;زۀ به انتقام واخلم په غصه او قهر کښې د هغه قومونو نه چې زما حُکم يې نۀ دے منلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21534, 'Micah 6:1', 'Micah', 6, 1, '&nbsp;هغې ته غوږ شئ څۀ چې مالِک خُدائ فرمائى، ودرېږه، خپله مقدمه د غرونو د وړاندې بيان کړه، پرېږده چې غرونه واورى چې تۀ څۀ وائې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21535, 'Micah 6:2', 'Micah', 6, 2, '&nbsp;واورئ، اے غرونو، د مالِک خُدائ اِلزام، تاسو غوږ ونيسئ. غوږ شئ، اے د زمکې ابدى بنيادونو. ځکه چې مالِک خُدائ د خپلو خلقو خلاف مقدمه کړې ده، هغه د بنى اِسرائيلو خلاف جرم لګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21536, 'Micah 6:3', 'Micah', 6, 3, '&nbsp;”زما خلقو، ما تاسو سره څۀ کړى دى؟ ما په تاسو څۀ بوج اچولے دے؟ ما له جواب راکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21537, 'Micah 6:4', 'Micah', 6, 4, '&nbsp;ما تاسو د مِصر نه بهر راوويستئ، او ما تاسو د غلامۍ د مُلک نه آزاد کړئ. ما موسىٰ سره د هارون او مريم درولېږل چې ستاسو لارښودنه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21538, 'Micah 6:5', 'Micah', 6, 5, '&nbsp;اے زما خلقو، هغه وخت راياد کړئ چې بلق د موآب بادشاه تاسو ته د نقصان رسولو کوشش کولو او بعور د بلعام زوئ څۀ جواب ورکړو. راياد کړئ خپل سفر د شطيم نه تر جِلجال پورې، نو تاسو ته به د مالِک خُدائ د صداقت کارونه معلوم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21539, 'Micah 6:6', 'Micah', 6, 6, '&nbsp;”زۀ د څۀ سره د مالِک خُدائ د وړاندې راشم او د لوئ خُدائ پاک په وړاندې سجده وکړم؟ آيا زۀ د هغۀ په وړاندې د يو کلن سخو د سوزېدونکو قربانو سره راشم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21540, 'Micah 6:7', 'Micah', 6, 7, '&nbsp;آيا مالِک خُدائ به په زرګونو ګډانو، او د زيتُونو د تېلو په زرګونو نِهرونو خوشحاله شى؟ آيا زۀ خپل وړومبے پېدا شوے ماشوم د خپلو ګناهونو دپاره پېش کړم، او د خپل بدن مېوه د خپل روح د ګناهونو دپاره؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21541, 'Micah 6:8', 'Micah', 6, 8, '&nbsp;هغۀ تاسو ته ووئيل، اے انسانه، چې ښېګړه څۀ ته وائى، او مالِک خُدائ درنه څۀ غواړى، يعنې چې اِنصاف کوئ او د رحم سره مينه کوئ او د خپل مالِک خُدائ سره په عاجزۍ سره تلل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21542, 'Micah 6:9', 'Micah', 6, 9, '&nbsp;غوږ شئ، مالِک خُدائ ښار ته آواز کوى. او ستا د نوم نه يرېدل حکمت دے. ”په هغه چوکه غور وکړئ او په هغۀ هم چا چې مقرر کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21543, 'Micah 6:10', 'Micah', 6, 10, '&nbsp;آيا زۀ د بدعمله په کور کښې په بدعملۍ سره ګټلے شوې خزانې هېرې کړم، او هغه کم ناپ تول چې پرې لعنت شوے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21544, 'Micah 6:11', 'Micah', 6, 11, '&nbsp;آيا زۀ هغه سړے بې‌سزا پرېږدم څۀ چې په تول کښې بې‌ايمانى کوى، او ورسره د غلط وزن تيلۍ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21545, 'Micah 6:12', 'Micah', 6, 12, '&nbsp;د هغې مالداره خلق ظالمان دى، د هغې خلق دروغژن دى او د هغوئ ژبې د دوکې خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21546, 'Micah 6:13', 'Micah', 6, 13, '&nbsp;نو بيا ستاسو د ګناهونو په وجه ما ستاسو تباه کول، او ورانول شروع کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21547, 'Micah 6:14', 'Micah', 6, 14, '&nbsp;تاسو به خوراک وکړئ، خو ماړه به نۀ شئ، او ستاسو خېټه به اوس هم تشه وى. تاسو به څيزونه جمع کړئ خو څۀ به بچ نۀ کړئ، ځکه چې تاسو څۀ جمع کوئ هغه به زۀ په تُوره ووهم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21548, 'Micah 6:15', 'Micah', 6, 15, '&nbsp;تاسو به غله وکَرئ، خو فصل به ونۀ رېبئ، تاسو به د زيتُونو نه تېل وباسئ خو دا به خپل ځان دپاره استعمال نۀ کړئ، تاسو به انګورو نه مے وباسئ، خو مے به ونۀ څښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21549, 'Micah 6:16', 'Micah', 6, 16, '&nbsp;تاسو د عُمرى بادشاه خراب قانون او د اخى‌اب د قوم ټول خراب رسمونه اختيار کړى دى. نو په دې وجه به زۀ تاسو بلکل تباه و برباد کړم او نورو خلقو ته به مو د عبرت يو مثال وګرځوم. څوک هم چې تاسو ګورى ستاسو نه به کرکه کوى او درپورې به مسخرې کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21550, 'Micah 7:1', 'Micah', 7, 1, '&nbsp;زۀ څومره بدبخته يم، زۀ د هغه مېوه راټولونکى په شان يم چې د فصل د راټولولو نه وروستو د خوړلو دپاره هيڅ څيز پېدا نۀ کړى. نۀ د انګورو يوه غنچه د انګورو په باغ کښې او نۀ د اينځر يو تازه دانه چې خپله لوږه ورباندې ماته کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21551, 'Micah 7:2', 'Micah', 7, 2, '&nbsp;مؤمنان د دُنيا نه ختم کړے شول، يو نېک هم پاتې نۀ شو. ټول انسانان په دې انتظار کښې دى چې وينه توئ کړى، هر يو خپل ورور په جال کښې راګېروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21552, 'Micah 7:3', 'Micah', 7, 3, '&nbsp;د هغوئ دواړه لاسونه په غلطو کارونو کښې تکړه دى، حکمرانان تحفې غواړى، قاضيان رشوت قبلوى، زورَور هغه حکم کوى چې څۀ يې خوښ وى. دوئ ټول يو ځائ سازشونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21553, 'Micah 7:4', 'Micah', 7, 4, '&nbsp;د هغوئ د ټولو نه ښۀ هم لکه د ازغن بوټى په شان دے، د هغوئ ډېر نېکان د ازغن بوټو د ډېرى نه هم خراب دى. خو ستاسو د فېصلې ورځ راغلې ده، ستاسو د سزا او وارخطايۍ وخت رارسېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21554, 'Micah 7:5', 'Micah', 7, 5, '&nbsp;په خپل ګاونډى باور مۀ کوه، مۀ په خپل دوست اعتبار کوه. تر دې چې څوک ستا په غېږ کښې اودۀ کيږى هغې سره هم په خپلو خبرو کولو کښې خيال کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21555, 'Micah 7:6', 'Micah', 7, 6, '&nbsp;ځکه چې نن سبا زوئ د پلار بې‌احترامى کوى، او لور د خپلې مور خلاف راپاڅى، اِنږور د خپلې خواښې مخالفت کوى. او د سړى دشمنان به د هغۀ د خپل کور خلق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21556, 'Micah 7:7', 'Micah', 7, 7, '&nbsp;خو زۀ به د مالِک خُدائ په امداد نظر ساتم، زۀ د خپل خلاصونکى خُدائ پاک انتظار کوم، زما خُدائ پاک به زما واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21557, 'Micah 7:8', 'Micah', 7, 8, '&nbsp;ما ته په حسرت سره مۀ ګوره، زما دشمنه، اګر کۀ زۀ غورزېدلے يم، زۀ به بيا راوچت شم. اګر کۀ زۀ په تيارۀ کښې ناست يم، خو مالِک خُدائ به زما رڼا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21558, 'Micah 7:9', 'Micah', 7, 9, '&nbsp;ځکه چې ما د هغۀ خلاف ګناه کړې ده، نو زۀ به د مالِک خُدائ قهر وزغمم، ترڅو چې هغه زما د مقدمې وکالت وکړى او زما حق قائم کړى. هغه به ما بهر رڼا ته راولى، زۀ به د هغۀ صداقت وګورم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21559, 'Micah 7:10', 'Micah', 7, 10, '&nbsp;بيا زما دشمنان به دا وګورى او دوئ به وشرميږى، هغه چا چې ما ته ووئيل چې، ”مالِک خُدائ ستا خُدائ پاک چرته دے؟“ زما سترګې به د هغې بربادى وګورى، اوس به هغه داسې د پښو لاندې شى لکه په کوڅو کښې چې خټې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21560, 'Micah 7:11', 'Micah', 7, 11, '&nbsp;ستا د دېوالونو جوړولو دپاره ورځ به راشى، په هغه ورځ به ستا سرحدونه لوئ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21561, 'Micah 7:12', 'Micah', 7, 12, '&nbsp;د ډېرو ځايونو نه به خلق ستا د عزت کولو دپاره راشى د اسور نه واخله د مِصر ښارونو پورې، او د مِصر نه واخله د فرات سيند پورې، او د لرى سمندرونو او غرونو پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21562, 'Micah 7:13', 'Micah', 7, 13, '&nbsp;زمکه به د اوسېدونکو په وجه او د هغوئ د بدو عملونو په نتيجه کښې د خلقو نه شاړه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21563, 'Micah 7:14', 'Micah', 7, 14, '&nbsp;اے مالِکه، د خپلو خلقو شپونتوب په خپلې لښتې سره وکړه، په خپله برخه رمې څوک چې د زرخيزه زمکې په مينځ کښې په ځنګل کښې اوسيږى، هغوئ پرېږده چې لکه د پخوا په شان په بسن او جِلعاد کښې وڅريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21564, 'Micah 7:15', 'Micah', 7, 15, '&nbsp;بيا مالِک خُدائ فرمائى چې، ”د هغه ورځو په شان کله چې تاسو د مِصر نه راووتلئ، زۀ به هغوئ ته خپلې معجزې وښايم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21565, 'Micah 7:16', 'Micah', 7, 16, '&nbsp;قومونه به وګورى او حېران به شى، هغوئ به د خپل ټول زور نه محروم شى. هغوئ به ګوته په خولۀ ودريږى او هغوئ به هيڅ نۀ اورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21566, 'Micah 7:17', 'Micah', 7, 17, '&nbsp;هغوئ به لکه د مار خاوره وخورى، لکه د هغه مخلوق چې په زمکه په سينه ښويږى. هغوئ به په رپېدو بهر د خپل غارونو نه راوځى، هغوئ به د يرې نه مالِک خُدائ زمونږ خُدائ پاک ته راوګرځى او تا نه به يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21567, 'Micah 7:18', 'Micah', 7, 18, '&nbsp;ستا په شان خُدائ څوک دے چې په خپلو غوره شوو کښې د بچ شوو خلقو جرمونه معاف کړى او د هغوئ ګناهونه نظر انداز کوى؟ ستا غصه د همېشه دپاره نۀ وى، خو تۀ په رحم ښودلو خوشحالېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21568, 'Micah 7:19', 'Micah', 7, 19, '&nbsp;تۀ به بيا په مونږ باندې مهربانه شې، تۀ به زمونږ ګناهونه د پښو لاندې کړې او زمونږ ټولې بې‌اِنصافۍ به د سمندر بېخ ته وغورزوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21569, 'Micah 7:20', 'Micah', 7, 20, '&nbsp;او د يعقوب اولاد ته به تۀ خپل رحم وښائې، تۀ به د اِبراهيم اولاد ته رښتونے يې، څنګه چې تا په تېر وخت کښې زمونږ پلار نيکۀ سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21570, 'Nahum 1:1', 'Nahum', 1, 1, '&nbsp;د ناحوم القوشى د رويا په کِتاب کښې د نينوه په حقله پېغام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21571, 'Nahum 1:2', 'Nahum', 1, 2, '&nbsp;مالِک خُدائ غېرتى او بدل اخستونکے خُدائ پاک دے، مالِک خُدائ بدل اخلى او د قهر نه ډک دے. او مالِک خُدائ د خپلو دشمنانو نه بدل اخلى او خپله غصه د خپلو دشمنانو خلاف جارى ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21572, 'Nahum 1:3', 'Nahum', 1, 3, '&nbsp;مالِک خُدائ په مزه غصه کيږى، خو هغه ډېر طاقتور هم دے، مالِک خُدائ به مجرم بغېر د سزا پرې نۀ ږدى. د هغۀ لاره په تېزه هوا او طوفان کښې ده، او وريځې د هغۀ د پښو دوړې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21573, 'Nahum 1:4', 'Nahum', 1, 4, '&nbsp;هغه سمندر رټى او اوچوى، هغه ټول سيندونه اوچوى. د بسن او د کرمل شينکے اوچوى، او د لبنان ګلونه مړاوى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21574, 'Nahum 1:5', 'Nahum', 1, 5, '&nbsp;د هغۀ د وړاندې غرونه لړزيږى، او غونډۍ ويلى کيږى. او زمکه د هغۀ په حضور کښې لړزيږى، دُنيا او هر هغه څوک چې په کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21575, 'Nahum 1:6', 'Nahum', 1, 6, '&nbsp;څوک د هغۀ قهر ته ودرېدے شى؟ څوک د هغۀ سخته غصه برداشت کولے شى؟ د هغۀ قهر لکه د اور په شان نازل شوے دے، ګټان د هغۀ په وړاندې ټوکړې ټوکړې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21576, 'Nahum 1:7', 'Nahum', 1, 7, '&nbsp;مالِک خُدائ ښۀ دے، د تکليف په وخت کښې هغه مضبوطه قلعه ده. او هغه د هغوئ حفاظت کوى څوک چې په هغۀ باور کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21577, 'Nahum 1:8', 'Nahum', 1, 8, '&nbsp;خو هغه به په يو زورَور سېلاب سره د نينوه خاتمه وکړى، هغه به خپل دشمنان د لحد تيارو ته ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21578, 'Nahum 1:9', 'Nahum', 1, 9, '&nbsp;هغوئ څوک چې د مالِک خُدائ خِلاف منصوبه جوړوى هغه به يې په يو ګزار سره سراسر برباد کړى. او د دوېم ګزار ضرورت به ورته نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21579, 'Nahum 1:10', 'Nahum', 1, 10, '&nbsp;د هغۀ دشمنان به د هغه سړو غوندې چې په ازغو کښې راګېر وى او چې په خپلو شرابو نشه وى، هغوئ به لکه د اوچو بوسو په شان وسوزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21580, 'Nahum 1:11', 'Nahum', 1, 11, '&nbsp;ستا نه، اے نينوه، څوک راغلو چې د مالِک خُدائ خلاف منصوبې جوړوى، څوک چې بې‌کاره مشوره ورکوونکى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21581, 'Nahum 1:12', 'Nahum', 1, 12, '&nbsp;مالِک خُدائ داسې فرمائى چې، ”اګر کۀ اسوريان اِتحاديان لرى او بې‌شمېره دى، هغوئ به ورک او تباه شى. اګر کۀ تاسو ما په تکليف کړئ، اے يهوداه، خو زۀ به تاسو نور په تکليف نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21582, 'Nahum 1:13', 'Nahum', 1, 13, '&nbsp;اوس به زۀ د اسوريانو جغ ستاسو د څټ نه اخوا کړم او ستاسو بيړۍ به وشلوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21583, 'Nahum 1:14', 'Nahum', 1, 14, '&nbsp;مالِک خُدائ ستا په حقله حکم کړے دے، اے نينوه، ”ستا اولاد به نۀ وى چې ستا نوم پرې پاتې شى. زۀ به هغه جوړ شوى تصويرونه او بُتان تباه کړم کوم چې ستاسو د معبودانو په عبادتخانو کښې دى. زۀ به ستا قبر تيار کړم، ځکه چې تۀ بدچلنه يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21584, 'Nahum 1:15', 'Nahum', 1, 15, '&nbsp;په غرونو نظر د هغه چا پښو ته واچوئ څوک چې ښۀ زېرے راوړى، او د امن و امان پېغام او د خلاصون اعلان کوى. اے يهوداه خپل اخترونه وکړئ، او خپلې عام منښتې کوئ. بدعمله به نور هيڅکله په تاسو قبضه نۀ کوى، هغوئ به په مکمل توګه تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21585, 'Nahum 2:1', 'Nahum', 2, 1, '&nbsp;اے نينوه، يو حمله کوونکے ستا خلاف راروان دے. د قلعې څوکيدارى کوه، د لار څوکيدارى کوه، خپل ځان په حفاظت کړه، خپل ټول قوت استعمال کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21586, 'Nahum 2:2', 'Nahum', 2, 2, '&nbsp;اګر کۀ تباه کوونکو هغوئ تباه کړى دى او د هغوئ د انګورو باغونه يې وران ويجاړ کړى دى خو مالِک خُدائ به د يهوداه شان او شوکت بيا قائم کړى لکه د اِسرائيل د شان او شوکت په شان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21587, 'Nahum 2:3', 'Nahum', 2, 3, '&nbsp;د فوجيانو ډالونه سرۀ دى، جنګيالو يې سرې جامې اغوستې دى. په جنګى ګاډو لګېدلې اوسپنې ځلېدې په هغه ورځ چې دوئ تيار وُو، او د دِيار نېزې يې په هوا کښې خوځولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21588, 'Nahum 2:4', 'Nahum', 2, 4, '&nbsp;جنګى ګاډۍ د طوفان غوندې په کوڅو کښې تېريږى، په چوکونو کښې مخکښې او وروستو ځى راځى. هغوئ لکه د چراغونو په شان پړقيږى، هغوئ لکه د برېښنا په شان په تېزه تېريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21589, 'Nahum 2:5', 'Nahum', 2, 5, '&nbsp;بادشاه خپلو آفسرانو ته چغې وهى، هغوئ په خپل رفتار کښې په لار تيندک خورى. د ښار دېوال ته په تېزه ورخلاص دى چې ځان ته د حملې مورچې تيارى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21590, 'Nahum 2:6', 'Nahum', 2, 6, '&nbsp;د سيند دروازې کولاو کړے شوې دى، او محل په راغورزېدو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21591, 'Nahum 2:7', 'Nahum', 2, 7, '&nbsp;د هغې مَلِکه بربنډه بوتلے شوه. د دې غلامانې جينکۍ لکه د ګوګوشتکو په شان ژړا کوى او هغوئ خپلې سينې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21592, 'Nahum 2:8', 'Nahum', 2, 8, '&nbsp;نينوه لکه د تالاب په شان دے او د دې اوبۀ روانې دى. ”ايسار شئ، ايسار شئ،“ هغوئ چغې وهى، خو هيڅ څوک شا ته نۀ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21593, 'Nahum 2:9', 'Nahum', 2, 9, '&nbsp;سپين زر لوټ کړئ. سرۀ زر لوټ کړئ. د دې د ذخيرې څۀ حد نشته، او د دې د ټولو خزانو دولت ډېر زيات دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21594, 'Nahum 2:10', 'Nahum', 2, 10, '&nbsp;هغه لوټ کړے شوه، خالى کړے شوه، ورانه ويجاړه شوه. زړونه کمزورى شول، پښې بې‌دمه شوې، بدنونه په رپېدو شول، هر مخ زېړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21595, 'Nahum 2:11', 'Nahum', 2, 11, '&nbsp;اوس نينوه هغه د زمرو غار چرته دے، هغه ځائ چرته چې هغوئ خپلو بچو له خوراک ورکولو، چرته چې زمرى او زمرۍ، او د دې بچى بغېر د څۀ ويرى نه ګرځېدل؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21596, 'Nahum 2:12', 'Nahum', 2, 12, '&nbsp;زمرى د خپلو بچو دپاره کافى ښکار وکړو او د خپلې زمرۍ دپاره د هغۀ ښکار په مرۍ غلے شو، خپل غار يې د ښکار د غوښې نه ډک کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21597, 'Nahum 2:13', 'Nahum', 2, 13, '&nbsp;زۀ ستاسو خِلاف يم، مالِک خُدائ ربُ الافواج فرمائى. زۀ به ستاسو جنګى ګاډۍ وسوزوم، او تُوره به ستاسو ځوانان زمرى ووژنى. زۀ به تاسو ته په زمکه ښکار پرې نۀ ږدم. ستاسو د پېغام ورکوونکو آوازونه به نور نۀ اورېدلے کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21598, 'Nahum 3:1', 'Nahum', 3, 1, '&nbsp;افسوس دې وى په وژونکى ښاريې، چې د دروغو او د لوټ شوى مال نه ډکه ده، کله هم د مظلومانو نه خالى شوى نۀ ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21599, 'Nahum 3:2', 'Nahum', 3, 2, '&nbsp;د کوړو ټسار ته، د پايو چغار ته، د آسونو ترپار ته، او د جنګى ګاډو درزار ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21600, 'Nahum 3:3', 'Nahum', 3, 3, '&nbsp;په آسونو سوارۀ حمله کوى، پړقېدونکې تُورې او ځلېدونکې نېزې ښکارى. هر طرف ته بې‌شمېره زخميان، د مړو ډيرى، بې‌شمېره مړى دى، او خلق په لاشونو تيندکونه خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');